reference_solution:
method Reverse(a: seq<int>) returns (r: seq<int>)
  ensures |r| == |a|
  ensures forall i :: 0 <= i < |a| ==> r[i] == a[|a| - 1 - i]
{
  r := [];
  var i := |a|;
  while i > 0
    invariant 0 <= i <= |a|
    invariant |r| == |a| - i
    invariant forall j :: 0 <= j < |a| - i ==> r[j] == a[|a| - 1 - j]
  {
    i := i - 1;
    r := r + [a[i]];
  }
}

